   let m := Mk_Mstatus (_get_Sstatus_bits s) in
   get_mstatus_UXL m.

Definition set_sstatus_UXL (s : Sstatus) (a : mword 2) : Sstatus :=
   let m := Mk_Mstatus (_get_Sstatus_bits s) in
