   write_reg htif_cmd_write_ref B0 >>
   write_reg htif_payload_writes_ref (EXTZ 4 ('b"0"  : mword 1))
    : M (unit).

Definition tick_platform '(tt : unit) : M (unit) := (htif_tick tt)  : M (unit).

