Definition execute_DIVW (rs2 : mword 5) (rs1 : mword 5) (rd : mword 5) (s : bool) : M (Retired) :=
   (haveMulDiv tt) >>= fun w__0 : bool =>
   (if sumbool_of_bool w__0 then
      (rX_bits rs1) >>= fun w__1 : mword 64 =>
