          (_limit_reduces _acc))
        : M (Retired)
    | C_JALR rs1 =>
       (_rec_execute (RISCV_JALR (EXTZ 12 ('b"0"  : mword 1), rs1, ra)) (Z.sub _reclimit 1)
          (_limit_reduces _acc))
        : M (Retired)
    | C_MV (rd, rs2) =>
       (_rec_execute (RTYPE (rs2, zreg, rd, RISCV_ADD)) (Z.sub _reclimit 1) (_limit_reduces _acc))
